function areaChk(t){if(t!='out'&&t!='in')return '';try{const H2=JSON.parse(JSON.stringify(HQ));const g=glob(H2);if(!(g.V>0))return '';let est,cur=C(t).base;if(t=='out'){H2.wk.out.A='';H2.blds.forEach(b=>{b.o_per=''});est=QF.out(H2,H2.wk.out,g).base}else{H2.wk.in.A='';H2.wk.in.C='';H2.blds.forEach(b=>{['n_1','n_2','n_3','n_4','n_5'].forEach(k=>{b[k]=''})});est=QF.in(H2,H2.wk.in,g).base}if(!(est>0)||(cur>=est*.5&&cur<=est*1.6))return '';return '입력된 '+(t=='in'?'내벽':'외벽')+' 면적('+F(cur,0)+'㎡)이 세대 정보로 추정한 면적('+F(est,0)+'㎡)과 '+Math.round(Math.abs(cur-est)/est*100)+'% 차이 납니다. 일부 동만 입력했거나 단위가 맞는지 확인하세요. 금액이 실제보다 매우 작거나 클 수 있습니다.'}catch(e){return ''}}
