function listHtml(){const a=lget();return `<details class="apc" ${HQ.od&&HQ.od.l?'open':''} ontoggle="hqO('l',this.open)"><summary><span class="apk">${sxIc('<ellipse cx="12" cy="6" rx="7" ry="3"/><path d="M5 6v6c0 1.7 3.1 3 7 3s7-1.3 7-3V6M5 12v6c0 1.7 3.1 3 7 3s7-1.3 7-3v-6"/>')}</span><b>견적 저장 · 불러오기</b><em class="apa">${a.length}건</em>${I('chev','apv')}</summary><div class="apb2"><div class="aptbt"><button type="button" onclick="aptSave()">${sxIc('<path d="M5 4h11l3 3v13H5z"/><path d="M8 4v5h7V4M8 20v-6h8v6"/>')}<span>${HQ.eid?'현재 견적 저장 (새 버전)':'현재 견적 저장'}</span></button><button type="button" onclick="aptNew()">${sxIc('<path d="M12 5v14M5 12h14"/>')}<span>새 견적</span></button></div>
 ${a.length?a.map(e=>`<div class="aptli${e.id==HQ.eid?' on':''}"><div class="zlt"><span class="zbi">${sxIc('<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 7h2M14 7h2M8 11h2M14 11h2M8 15h2M14 15h2"/>')}</span><div class="aptlt"><b>${esc(e.name)}</b><small>v${e.ver} · ${dstr(e.ts)} · ${won(e.total)}원</small></div>${sxIc('<path d="M9 6l6 6-6 6"/>')}</div><div class="aptla"><button type="button" onclick="aptLoad('${e.id}')">${sxIc('<path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/>')}<span>불러오기</span></button><button type="button" onclick="aptCopy('${e.id}')">${sxIc('<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2"/>')}<span>복제</span></button><button type="button" onclick="aptDel('${e.id}')">${sxIc('<path d="M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3"/>')}<span>삭제</span></button></div>${(e.hist||[]).length?`<details class="apthl"><summary>이전 버전 ${(e.hist||[]).length}개</summary>${(e.hist||[]).map((h,i)=>`<div class="aphr"><b>v${h.ver}</b><span>${dstr(h.ts)} · ${won(h.total)}원</span><button type="button" onclick="aptLoad('${e.id}',${i})">불러오기</button></div>`).join('')}</details>`:''}</div>`).join(''):'<div class="apno">저장된 견적이 없습니다</div>'}<div class="apnote">저장은 이 기기(브라우저)에만 됩니다. 저장할 때마다 새 버전이 되고 이전 버전은 개수 제한 없이 모두 보관합니다.</div></div></details>`}
/* ===== 출력: 견적서 · 원가계산서 · 세부 내역서 (한 번 계산한 결과로 생성) ===== */
const RWS=[['M','재료비 (직접재료비)'],['L','직접노무비'],['IL','간접노무비'],['E','직접경비'],['ac','산재보험료'],['emp','고용보험료'],['hl','건강보험료'],['pn','연금보험료'],['ca','노인장기요양보험료'],['rt','퇴직금공제부금비'],['sf','산업안전보건관리비'],['as','석면분담금'],['wc','임금채권부담금'],['et','기타경비'],['env','환경보전비'],['S','합 계'],['gm','일반관리비'],['pf','이 윤'],['T','총원가'],['vat','부가가치세'],['G','총공사비']];
function repData(){const ts=WT.filter(inc),R=ts.map(t=>({t,r:C(t)})),S={};RWS.forEach(([k])=>S[k]=R.reduce((s,x)=>s+x.r.c[k],0));
 const ck=[],ok=(b,m)=>ck.push([b,m]);
 ok(S.T+S.vat===S.G,'공종 원가 합계 + 부가가치세 = 총 견적금액');
 R.forEach(x=>{const it=x.r.items.reduce((s,i)=>s+i.am+i.al+i.ae,0);ok(it===x.r.c.M+x.r.c.L+x.r.c.E,TYN[x.t]+': 내역서 합계 = 원가계산서 직접비 (재료+노무+경비)');ok(x.r.c.vat===Math.trunc(x.r.c.T*x.r.c.CR.vat),TYN[x.t]+': 부가가치세 원 단위 절사 일치')});
 return {ts,R,S,ck}}
const nz=v=>v?won(v):'-';
function repQuote(d){const nm=esc(HQ.name||'○○아파트');
 return `<div class="rpa4"><h2>공사금액 견적서</h2><div class="rpm"><span>공사명</span><b>${nm} 보수공사</b></div><div class="rpm"><span>견적일</span><b>${dstr(Date.now()).slice(0,10)}</b></div>
 <table><tr><th>No</th><th>공종</th><th>공사원가</th><th>부가세</th><th>합계</th></tr>${d.R.map((x,i)=>`<tr><td>${i+1}</td><td class="l">${TYN[x.t]}</td><td class="n">${won(x.r.c.T)}</td><td class="n">${won(x.r.c.vat)}</td><td class="n">${won(x.r.c.G)}</td></tr>`).join('')}<tr class="tt"><td colspan="2">총 견적금액</td><td class="n">${won(d.S.T)}</td><td class="n">${won(d.S.vat)}</td><td class="n">${won(d.S.G)}</td></tr></table>
 <div class="rpn">비고<br>· 본 견적은 2026 셀프견적 기준(조달청 2026.04.01 간접공사비, 예정가격작성기준 제34호)으로 산출한 공사비 추정 참고자료이며, 실제 시공은 현장 여건에 따라 조정됩니다.<br>· 부가가치세 10% 포함, 원 단위 미만 절사.${prodNote(d)}</div></div>`}
function repCost(d){const rows=RWS.filter(([k])=>d.R.some(x=>x.r.c[k]));
 return `<div class="rpa4"><h2>공사원가계산서</h2><table><tr><th>비목</th>${d.R.map(x=>`<th>${TYN[x.t]}</th>`).join('')}<th>합계</th></tr>${rows.map(([k,l])=>`<tr class="${['S','T','G'].includes(k)?'tt':''}"><td class="l">${l}</td>${d.R.map(x=>`<td class="n">${nz(x.r.c[k])}</td>`).join('')}<td class="n">${nz(d.S[k])}</td></tr>`).join('')}</table>
 <div class="rpn">적용 요율: ${d.R.map(x=>{const Q=x.r.c.CR;return TYN[x.t]+' 간접노무비 '+(+(Q.ind*100).toFixed(3))+'% · 안전관리비 '+(+((x.r.c.sm==3?Q.sf3:x.r.c.sm==2?Q.sf2:Q.sf1)*100).toFixed(3))+'%'}).join(' / ')}<br>일반관리비 ${d.R[0]?d.R[0].r.c.CR.gm:4}% · 이윤 ${d.R[0]?d.R[0].r.c.CR.pf:10}% · 부가가치세 10%</div></div>`}
function repItems(d){const pl=HQ.plog||[];
 return d.R.map(x=>{const it=x.r.items.filter(i=>i.q>0);return `<div class="rpa4"><h2>공종별 세부 내역서 · ${TYN[x.t]}</h2><table><tr><th rowspan="2">품명</th><th rowspan="2">규격</th><th rowspan="2">단위</th><th rowspan="2">수량</th><th colspan="2">재료비</th><th colspan="2">노무비</th><th colspan="2">경비</th><th rowspan="2">합계</th></tr><tr><th>단가</th><th>금액</th><th>단가</th><th>금액</th><th>단가</th><th>금액</th></tr>
 ${it.length?it.map(i=>`<tr><td class="l">${esc(i.nm)}</td><td class="l">${esc(i.sp)}</td><td>${i.u}</td><td class="n">${F(i.q,3).replace(/\.?0+$/,'')}</td><td class="n">${won(i.p[0])}</td><td class="n">${won(i.am)}</td><td class="n">${won(i.p[1])}</td><td class="n">${won(i.al)}</td><td class="n">${won(i.p[2])}</td><td class="n">${won(i.ae)}</td><td class="n">${won(i.am+i.al+i.ae)}</td></tr>`).join(''):'<tr><td colspan="11">수량이 있는 항목이 없습니다</td></tr>'}
 <tr class="tt"><td colspan="5">소 계</td><td class="n">${won(x.r.c.M)}</td><td></td><td class="n">${won(x.r.c.L)}</td><td></td><td class="n">${won(x.r.c.E)}</td><td class="n">${won(x.r.c.M+x.r.c.L+x.r.c.E)}</td></tr></table></div>`}).join('')
 +(pl.length?`<div class="rpa4"><h2>단가 수정 내역</h2><table><tr><th>일시</th><th>공종</th><th>품명</th><th>구분</th><th>변경 전</th><th>변경 후</th></tr>${pl.slice().reverse().map(g=>`<tr><td>${dstr(g.ts)}</td><td class="l">${TYN[g.t]||g.t}</td><td class="l">${esc(g.nm)}</td><td>${g.f}</td><td class="n">${g.o==null?'-':won(g.o)}</td><td class="n">${g.n==null?'기준값 복원':won(g.n)}</td></tr>`).join('')}</table></div>`:'')}
function repCheck(d){return `<div class="rpa4 rpc"><h2>합계 검증</h2>${d.ck.map(([b,m])=>`<div class="${b?'ok':'ng'}">${b?'✓':'✕'} ${m}</div>`).join('')}<div class="rpn">단가·요율 기준: 2026 셀프견적 기준. 수정한 단가는 ‘단가 수정 내역’에 기록됩니다.</div></div>`}
let RPT='q';
function repHtml(){const d=repData();if(!d.ts.length)return '<div class="rpa4"><div class="apno">견적에 넣을 공종이 없습니다<br><small>단지 정보에서 공종을 체크하세요</small></div></div>';return (RPT=='q'?repQuote(d):RPT=='c'?repCost(d):repItems(d))+repCheck(d)}
window.aptRep=()=>{aptRepClose();const e=document.createElement('div');e.id='aptrp';e.innerHTML=`<div class="rph"><button type="button" onclick="aptRepClose()">← 닫기</button><b>견적 출력</b><span style="flex:1"></span><button type="button" onclick="aptPrint()">인쇄 / PDF</button><button type="button" onclick="aptXls()">Excel</button></div><div class="rpt">${[['q','견적서'],['c','원가계산서'],['i','세부 내역서']].map(([k,l])=>`<button type="button" data-k="${k}" class="${k==RPT?'on':''}" onclick="aptRepTab('${k}')">${l}</button>`).join('')}</div><div class="rpb" id="aptrpb">${repHtml()}</div>`;document.body.appendChild(e)};
window.aptRepTab=k=>{RPT=k;const e=document.getElementById('aptrp');if(!e)return;e.querySelectorAll('.rpt button').forEach(b=>b.classList.toggle('on',b.dataset.k==k));document.getElementById('aptrpb').innerHTML=repHtml();document.getElementById('aptrpb').scrollTop=0};
window.aptRepClose=()=>{const e=document.getElementById('aptrp');if(e)e.remove()};
window.aptPrint=()=>{try{window.print()}catch(e){tt('이 기기에서는 인쇄를 지원하지 않습니다')}};
window.aptXls=()=>{const d=repData();if(!d.ts.length)return tt('견적에 넣을 공종을 선택하세요');const prev=RPT;let h='';RPT='q';h+=repQuote(d);RPT='c';h+=repCost(d);h+=repItems(d);h+=repCheck(d);RPT=prev;
 const html='<html><head><meta charset="utf-8"><style>table{border-collapse:collapse}td,th{border:1px solid #999;padding:3px 6px;mso-number-format:"\\\\@"}td.n{text-align:right}h2{font-size:14pt}</style></head><body>'+h+'</body></html>';const nm=(HQ.name||'공동주택')+'_견적서.xls';
 try{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\\ufeff'+html],{type:'application/vnd.ms-excel;charset=utf-8'}));a.download=nm;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);tt('Excel 파일을 저장했습니다')}catch(e){tt('저장할 수 없습니다')}};

function sitePanel(){return sitePanel0()+listHtml()}
function itemsHtml(t,r,all){const rows=r.items.filter(x=>all||x.q>0);if(!rows.length)return '<div class="apno">수량이 있는 항목이 없습니다<br><small>면적이나 옵션을 입력하세요</small></div>';
 return rows.map(x=>{const tp=x.p[0]+x.p[1]+x.p[2];return `<div class="hqi${x.q>0?'':' z'}"><div class="hqn"><b>${esc(x.nm)}</b>${x.sp?`<small>${esc(x.sp)}</small>`:''}</div><div class="hqm"><span>${F(x.q,3).replace(/\.?0+$/,'')} ${x.u} × ${won(tp)}</span><b>${won(x.am+x.al+x.ae)}원</b></div></div>`}).join('')}
function resHtml(t){const r=C(t),c=r.c;
 const ar=r.area.map(a=>`<div class="hqk${/③/.test(a[2]||'')?' est':''}"><small>${a[0]}${a[2]&&a[2]!='—'?' · '+a[2]:''}${/③/.test(a[2]||'')?' (추정치)':''}</small><b>${F(a[1],2)}<i>㎡</i></b></div>`).join('');
 const ex=r.extra.length?`<div class="hqex">${r.extra.map(e=>`${e[0]} ${F(e[1],1)}${e[2]}`).join(' · ')}</div>`:'';
 return `${vaHtml(t)}<details class="sxc sxd ov" ${HQ.od&&HQ.od.ov===0?'':'open'} ontoggle="hqO('ov',this.open)"><summary><div class="sxt"><i>${I('bld')}</i><b>단지 개요</b></div>${sxIc('<path d="M6 9l6 6 6-6"/>')}</summary><div class="ovg">${ar}<div class="hqk ovt"><small>총공사비 (부가세 포함)</small><b>${won(c.G)}<i>원</i></b></div></div>${ex}<div class="hqsub"><span>공사원가 ${won(c.T)}원</span><span>부가세 ${won(c.vat)}원</span></div></details>
 ${basisCard(t,r)}
 <details class="apc" ${HQ.od&&HQ.od.i?'open':''} ontoggle="hqO('i',this.open)"><summary onclick="event.preventDefault();hqDet('i')"><span class="apk">${I('doc')}</span><b>공종별 내역서</b><em class="apa">${r.items.filter(x=>x.q>0).length}건</em>${I('chev','apv')}</summary><div class="apb2"><div class="hqil">${itemsHtml(t,r,HQ.all)}</div><label class="hqall"><input type="checkbox" ${HQ.all?'checked':''} onchange="hqAll(this.checked)"> 수량 0 항목도 보기</label></div></details>
 <details class="apc" ${HQ.od&&HQ.od.c?'open':''} ontoggle="hqO('c',this.open)"><summary onclick="event.preventDefault();hqDet('c')"><span class="apk">${I('won')}</span><b>공사 원가계산서</b><em class="apa">${won(c.G)}</em>${I('chev','apv')}</summary><div class="apb2"><div class="hqcs">${costHtml(c)}</div><div class="apnote">${basisNote()}</div></div></details>
 <details class="apc" ${HQ.od&&HQ.od.p?'open':''} ontoggle="hqO('p',this.open)"><summary onclick="event.preventDefault();hqDet('p')"><span class="apk">${I('ruler')}</span><b>단가 수정</b><em class="apa">${Object.keys(HQ.wk[t].pr||{}).length?'수정됨':'기준값'}</em>${I('chev','apv')}</summary><div class="apb2">${priceHtml(t,r)}</div></details>`}
window.hqO=(k,o)=>{HQ.od=HQ.od||{};HQ.od[k]=o?1:0;save()};window.hqAll=v=>{HQ.all=v?1:0;save();upd()};
function priceHtml(t,r){return `<div class="apnote">재료비 · 노무비 · 경비 단가(원)를 수정하면 이 공종 내역서에 반영됩니다. 2026 기준 단가표 값이 기본입니다.</div>`+r.items.map(x=>`<div class="hqp"><b>${esc(x.nm)}${x.sp?' · '+esc(x.sp):''} <small>/${x.u}</small></b><div class="hqp3">${[0,1,2].map(i=>`<label><span>${['재료','노무','경비'][i]}</span><input type="number" inputmode="decimal" value="${x.p[i]}" onchange="hqP('${t}',${x.r},${i},this.value)"></label>`).join('')}</div></div>`).join('')+`<button type="button" class="apx hqrs" onclick="hqPR('${t}')">${I('trash')}<span>이 공종 단가 초기화</span></button>`}
window.hqP=(t,r,i,v)=>{const w=HQ.wk[t];w.pr=w.pr||{};const m=HP[t][r];const cur=C(t).items.find(x=>x.r==r);w.pr[r]=w.pr[r]||(cur?cur.p.slice():[m[3],m[4],m[5]]);const _o=w.pr[r][i];w.pr[r][i]=n(v);if(_o!==n(v)){HQ.plog=HQ.plog||[];HQ.plog.push({t,r:+r,nm:m[0]+(m[1]?' '+m[1]:''),f:['재료','노무','경비'][i],o:_o,n:n(v),ts:Date.now()});if(HQ.plog.length>200)HQ.plog.shift()}save();upd()};
window.hqPR=t=>ask('이 공종의 단가를 기준값으로 되돌릴까요?',()=>{if(Object.keys(HQ.wk[t].pr||{}).length){HQ.plog=HQ.plog||[];HQ.plog.push({t,r:0,nm:'전체 단가',f:'-',o:null,n:null,ts:Date.now()})}delete HQ.wk[t].pr;save();rerender()});
